You are a test engineer for a robot pick-and-place policy. Propose RISKY regions of the scenario parameter space where the policy is most likely to fail, so they can be tested. You do not decide pass or fail and you do not know the results. Use only the listed parameters and stay inside their bounds.

Reply with a single JSON object matching this JSON Schema, and nothing else:
{"additionalProperties": false, "description": "What the model's JSON is parsed into FIRST. Individual regions are triaged one by one by `triage`, so one bad region\ndoes not discard the others.", "properties": {"regions": {"items": {"additionalProperties": true, "type": "object"}, "maxItems": 12, "minItems": 1, "title": "Regions", "type": "array"}}, "required": ["regions"], "title": "RawProposal", "type": "object"}

{
 "task": "A simulated parallel-jaw gripper picks up a cube from a table and places it in a circular target zone 30 cm away, passing over a 6 cm low wall. The policy is a fixed controller with a few tunable numbers.",
 "scenario_parameters": {
  "mass_kg": {
   "doc": "cube mass in kg",
   "min": 0.05,
   "max": 1.0
  },
  "friction": {
   "doc": "contact friction coefficient of the cube",
   "min": 0.1,
   "max": 1.2
  },
  "size_m": {
   "doc": "cube edge length in metres",
   "min": 0.03,
   "max": 0.08
  },
  "pos_offset_x": {
   "doc": "cube x offset from nominal position, metres",
   "min": -0.08,
   "max": 0.08
  },
  "pos_offset_y": {
   "doc": "cube y offset from nominal position, metres",
   "min": -0.08,
   "max": 0.08
  },
  "sensor_noise_m": {
   "doc": "std of Gaussian noise on the perceived cube position, metres",
   "min": 0.0,
   "max": 0.03
  },
  "gripper_delay_steps": {
   "doc": "gripper actuation latency in 240 Hz physics steps (integer)",
   "min": 0,
   "max": 20
  }
 },
 "request": "Return 3 to 6 regions. Each: a short name, a one-sentence physical rationale, and ranges [lo, hi] for the parameters that define the region (omitted parameters span their full range).",
 "valid_parameter_names": [
  "mass_kg",
  "friction",
  "size_m",
  "pos_offset_x",
  "pos_offset_y",
  "sensor_noise_m",
  "gripper_delay_steps"
 ],
 "rules": [
  "In 'ranges' use ONLY the names in valid_parameter_names as keys. Nothing else is a valid key (the robot's own control settings are NOT scenario parameters).",
  "Constrain AT MOST 3 parameters per region; leave all others out.",
  "Each range is [lo, hi] with lo <= hi, inside that parameter's min and max.",
  "Each constrained range should span at least 30% of that parameter's min-max width, so that the region covers at least 2% of the whole parameter space (the product of the constrained parameters' relative widths). Do not use tiny ranges.",
  "Your rationale is treated as an unverified opinion and is only a hint for people reading the test plan."
 ]
}

reply:
{
  "regions": [
    {
      "name": "TransitionalMass",
      "rationale": "Light cubes may behave differently when slipping when moving across the wall.",
      "ranges": {
        "mass_kg": [0.05, 0.15]
      }
    },
    {
      "name": "HighFrictionWallTraverse",
      "rationale": "High friction could generate pitching moment that tips the cube when crossing the wall.",
      "ranges": {
        "friction": [0.80, 1.20],
        "pos_offset_y": [-0.02, 0.02],
        "size_m": [0.05, 0.08]
      }
    },
    {
      "name": "LargeDelayedGripper",
      "rationale": "Long actuation latency can cause gripper close after the wall is passed.",
      "ranges": {
        "gripper_delay_steps": [12, 20],
        "mass_kg": [0.30, 1.0],
        "sensor_noise_m": [0.010, 0.030]
      }
    },
    {
      "name": "NoisyMisplacedOffset",
      "rationale": "High sensor noise combined with offset can misestimate position needed to clear the wall.",
      "ranges": {
        "sensor_noise_m": [0.020, 0.030],
        "pos_offset_x": [-0.08, -0.02],
        "pos_offset_y": [-0.08, 0.08]
      }
    },
    {
      "name": "LargeSmallishCube",
      "rationale": "Large but not too large cubes may slip at the wall when friction is medium.",
      "ranges": {
        "size_m": [0.04, 0.07],
        "friction": [0.60, 0.95],
        "gripper_delay_steps": [6, 12]
      }
    },
    {
      "name": "NarrowMisplacedLowNoise",
      "rationale": "Small positional errors with low noise might slip when the cube is offset toward the wall edge.",
      "ranges": {
        "pos_offset_x": [-0.03, 0.03],
        "size_m": [0.035, 0.06],
        "sensor_noise_m": [0.0, 0.005]
      }
    }
  ]
}

